/** static u32 GetScore(u8 playerId) */
export function GetScore(playerId: any): any {
  let i: any = null;
      let scoreLost, score = 0;

       
      for (i = 0; i < BERRY_MISSED; i++)
          score += sGame.berryResults[playerId][i] * sBerryScoreMultipliers[i];

       
      scoreLost = sGame.berryResults[playerId][BERRY_MISSED] * sBerryScoreMultipliers[BERRY_MISSED];

      if (score <= scoreLost)
          return 0;
      else
          return score - scoreLost;
}

/** static u32 GetHighestScore(void) */
export function GetHighestScore(): any {
  let i, numPlayers = sGame.numPlayers;
      let maxScore: any = GetScore(0);

      for (i = 1; i < numPlayers; i++)
      {
          let score: any = GetScore(i);
          if (score > maxScore)
              maxScore = score;
      }
      return Min(maxScore, MAX_SCORE);
}

/** static u32 GetHighestBerryResult(u8 berryId) */
export function GetHighestBerryResult(berryId: any): any {
  let i, numPlayers = sGame.numPlayers;
      let maxScore: any = sGame.berryResults[0][berryId];

      for (i = 0; i < numPlayers; i++)
      {
          let score: any = sGame.berryResults[i][berryId];
          if (score > maxScore)
              maxScore = score;
      }
      return maxScore;
}

/** static u32 GetScoreByRanking(u8 ranking) */
export function GetScoreByRanking(ranking: any): any {
  let scores, temp;
      let unsorted: any = TRUE;
      let i: any = null;
      let numPlayers: any = sGame.numPlayers;

      for (i = 0; i < numPlayers; i++)
          scores[i] = temp = GetScore(i);

       
      while (unsorted)
      {
          unsorted = FALSE;
          for (i = 0; i < numPlayers - 1; i++)
          {
              if (scores[i] < scores[i + 1])
              {
                  SWAP(scores[i], scores[i + 1], temp);
                  unsorted = TRUE;
              }
          }
      }

      return scores[ranking];
}

/** static u32 SetScoreResults(void) */
export function SetScoreResults(): any {
  let i, ranking = 0, nextRanking = 0, playersRanked = 0;
      let numPlayers: any = sGame.numPlayers;

      GetHighestScore();  

      if (GetHighestScore() == 0)
      {
           
           
           
          for (i = 0; i < numPlayers; i++)
          {
              sGame.scoreResults[i].ranking = MAX_RFU_PLAYERS - 1;
              sGame.scoreResults[i].score = 0;
          }
      }

       
      for (i = 0; i < numPlayers; i++)
          sGame.scoreResults[i].score = Min(GetScore(i), MAX_SCORE);

       
      do
      {
          let score: any = GetScoreByRanking(ranking);
          let curRanking: any = nextRanking;

           
           
           
          for (i = 0; i < numPlayers; i++)
          {
              if (score == sGame.scoreResults[i].score)
              {
                  sGame.scoreResults[i].ranking = curRanking;
                  nextRanking++;
                  playersRanked++;
              }
          }
          ranking = nextRanking;
      } while (playersRanked < numPlayers);

      return 0;
}

