/** static void SpriteCB_Dodrio(struct Sprite *sprite) */
export function SpriteCB_Dodrio(sprite: any): any {
  switch (sprite.sState)
      {
      case 0:
          break;
      case 1:
          DoDodrioMissedAnim(sprite);
          break;
      case 2:
          DoDodrioIntroAnim(sprite);
          break;
      }
}

/** static void StartDodrioMissedAnim(u8 unused) */
export function StartDodrioMissedAnim(unused: any): any {
  let sprite: any =gSprites[sDodrioSpriteIds[GetMultiplayerId()]];
      sprite.sState = 1;
      sprite.sTimer = 0;
      sprite.sUnused1 = 0;
      sprite.sUnused2 = 0;
      sprite.sUnused3 = 0;
}

/** static void StartDodrioIntroAnim(u8 unused) */
export function StartDodrioIntroAnim(unused: any): any {
  let sprite: any =gSprites[sDodrioSpriteIds[GetMultiplayerId()]];
      sprite.sState = 2;
      sprite.sTimer = 0;
      sprite.sUnused1 = 0;
      sprite.sUnused2 = 0;
      sprite.sUnused3 = 0;
}

/** static u32 DoDodrioMissedAnim(struct Sprite *sprite) */
export function DoDodrioMissedAnim(sprite: any): any {
  let x: any = null;
      let state: any = (++sprite.sTimer / 2) % 4;

      if (sprite.sTimer >= 3)
      {
          switch (state)
          {
          default:
              x = 1;
              break;
          case 1:
          case 2:
              x = -1;
              break;
          }

          sprite.x += x;
          if (++sprite.sTimer >= 40)
          {
              sprite.sState = 0;
              sprite.x = GetDodrioXPos(0, GetNumPlayers());
          }
      }

      return 0;
}

/** static u32 DoDodrioIntroAnim(struct Sprite *sprite) */
export function DoDodrioIntroAnim(sprite: any): any {
  let pickState: any = (++sprite.sTimer / FRAMES_PER_STATE) % NUM_INTRO_PICK_STATES;

       
      if (sprite.sTimer % FRAMES_PER_STATE == 0 && pickState != PICK_NONE)
          PlaySE(SE_M_CHARM);

      if (sprite.sTimer >= FRAMES_PER_STATE * NUM_INTRO_PICK_STATES * 2)
      {
           
          sprite.sState = 0;
          pickState = PICK_NONE;
      }
      SetDodrioAnim(GetMultiplayerId(), pickState);
      return 0;
}

