/** static s16 GetDodrioXPos(u8 playerId, u8 numPlayers) */
export function GetDodrioXPos(playerId: any, numPlayers: any): any {
  let x: any = 0;
      switch (numPlayers)
      {
      case 1:
          x = 15;
          break;
      case 2:
          switch (playerId)
          {
              case 0: x = 12; break;
              case 1: x = 18; break;
          }
          break;
      case 3:
          switch (playerId)
          {
              case 0: x = 15; break;
              case 1: x = 21; break;
              case 2: x =  9; break;
          }
          break;
      case 4:
          switch (playerId)
          {
              case 0: x = 12; break;
              case 1: x = 18; break;
              case 2: x = 24; break;
              case 3: x =  6; break;
          }
          break;
      case 5:
          switch (playerId)
          {
              case 0: x = 15; break;
              case 1: x = 21; break;
              case 2: x = 27; break;
              case 3: x =  3; break;
              case 4: x =  9; break;
          }
          break;
      }

      return x * 8;
}

